import { beforeAll, afterAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberRepo from "@/server/repositories/member-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("tmppart-north");
  acme = await createTenant("tmppart-acme");
});

afterAll(() => cleanup());

describe("tmp getIssueParticipants", () => {
  it("unions author, assignee, live commenters; dedupes; viewer may call", async () => {
    const issue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "p1", assigneeId: north.userIds.admin }),
    );
    // member is author AND commenter (dedupe); owner commented (live)
    await commentService.createComment(north.actors.member, {
      orgId: north.org.id, issueId: issue.id, body: "a", parentId: null, mentionedUserIds: [],
    });
    await commentService.createComment(north.actors.owner, {
      orgId: north.org.id, issueId: issue.id, body: "b", parentId: null, mentionedUserIds: [],
    });

    const ids = await commentService.getIssueParticipants(north.actors.viewer, north.org.id, issue.id);
    expect([...ids].sort()).toEqual(
      [north.userIds.member, north.userIds.admin, north.userIds.owner].sort(),
    );
    expect(ids.length).toBe(new Set(ids).size);
  });

  it("excludes users whose only comments were deleted", async () => {
    const issue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "p2" }),
    );
    const c = await commentService.createComment(north.actors.owner, {
      orgId: north.org.id, issueId: issue.id, body: "gone", parentId: null, mentionedUserIds: [],
    });
    await commentService.deleteComment(north.actors.owner, { orgId: north.org.id, commentId: c.id });

    const ids = await commentService.getIssueParticipants(north.actors.member, north.org.id, issue.id);
    expect(ids).toEqual([north.userIds.member]);
  });

  it("drops a removed member even when they authored the issue", async () => {
    const issue = await issueService.createIssue(
      north.actors.admin,
      issueInput(north.org.id, north.project.id, { title: "p3", assigneeId: north.userIds.viewer }),
    );
    const removed = await memberRepo.findMember(north.org.id, north.userIds.admin);
    await memberRepo.archiveMember(north.org.id, removed!.id);

    const ids = await commentService.getIssueParticipants(north.actors.owner, north.org.id, issue.id);
    expect(ids).not.toContain(north.userIds.admin);
    expect(ids).toContain(north.userIds.viewer);
  });

  it("rejects a foreign orgId with the tenant-scope error", async () => {
    const issue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "p4" }),
    );
    await expect(
      commentService.getIssueParticipants(north.actors.member, acme.org.id, issue.id),
    ).rejects.toMatchObject({ code: "tenant_scope_violation" });
  });

  it("rejects another org's issue id with not_found", async () => {
    const acmeIssue = await issueService.createIssue(
      acme.actors.member,
